static NSCache *PVXMetadataCache;
static NSMutableDictionary *PVXMetadataWaiters;
static NSString *PVXMetadataText(id v,NSUInteger n){return [v isKindOfClass:NSString.class]?[v substringToIndex:MIN(n,[v length])]:@"";}
static NSURL *PVXMetadataURL(NSDictionary *row){NSString *text=PVXMetadataText(row[@"url"],16384);NSURL *u=[NSURL URLWithString:text];return u.host.length&&[@[@"http",@"https"] containsObject:u.scheme.lowercaseString]?u:nil;}
static NSString *PVXMetadataBytes(long long bytes){return bytes>0?[NSByteCountFormatter stringFromByteCount:bytes countStyle:NSByteCountFormatterCountStyleDecimal]:@"大小未知";}
static NSString *PVXMetadataCodec(AVAssetTrack *track){if(!track||!track.formatDescriptions.count)return @"";CMFormatDescriptionRef d=(__bridge CMFormatDescriptionRef)track.formatDescriptions.firstObject;FourCharCode c=CMFormatDescriptionGetMediaSubType(d);switch(c){case kCMVideoCodecType_H264:return @"H.264";case kCMVideoCodecType_HEVC:return @"HEVC";case kCMVideoCodecType_VP9:return @"VP9";case kCMVideoCodecType_AV1:return @"AV1";default:return @"";}}
static void PVXMetadataDeliver(NSString *key,NSDictionary *value){if(value) [PVXMetadataCache setObject:value forKey:key];NSArray *wait=[PVXMetadataWaiters[key] copy]?:@[];[PVXMetadataWaiters removeObjectForKey:key];for(void(^block)(NSDictionary*) in wait)block(value?:@{});}
static void PVXMetadataStart(NSDictionary *row,NSArray *cookies,NSString *ua,NSString *key){NSURL *url=PVXMetadataURL(row);if(!url){PVXMetadataDeliver(key,@{@"quality":@"不是媒体 URL",@"sizeText":@"不可下载"});return;}NSMutableDictionary *result=[@{@"quality":@"分辨率未知",@"sizeText":([url.path.lowercaseString containsString:@".m3u8"]||[url.path.lowercaseString containsString:@".mpd"])?@"HLS/DASH · 大小下载后确定":@"大小未知"} mutableCopy];NSURLSessionConfiguration *cfg=NSURLSessionConfiguration.ephemeralSessionConfiguration;cfg.HTTPCookieStorage=nil;cfg.HTTPShouldSetCookies=NO;cfg.timeoutIntervalForRequest=20;cfg.timeoutIntervalForResource=30;NSMutableURLRequest *request=[NSMutableURLRequest requestWithURL:url cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:20];request.HTTPMethod=@"HEAD";if(ua.length)[request setValue:ua forHTTPHeaderField:@"User-Agent"];NSURLComponents *ref=[NSURLComponents componentsWithString:PVXMetadataText(row[@"page"],16384)];ref.user=nil;ref.password=nil;ref.fragment=nil;if(ref.URL)[request setValue:ref.URL.absoluteString forHTTPHeaderField:@"Referer"];if(cookies.count){NSDictionary *fields=[NSHTTPCookie requestHeaderFieldsWithCookies:cookies];if(fields[@"Cookie"])[request setValue:fields[@"Cookie"] forHTTPHeaderField:@"Cookie"];}NSURLSession *session=[NSURLSession sessionWithConfiguration:cfg];[[session dataTaskWithRequest:request completionHandler:^(NSData *data,NSURLResponse *response,NSError *error){NSHTTPURLResponse *http=[response isKindOfClass:NSHTTPURLResponse.class]?(id)response:nil;long long length=http.expectedContentLength;if(length>0)result[@"sizeText"]=PVXMetadataBytes(length);[session finishTasksAndInvalidate];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSMutableDictionary *options=[NSMutableDictionary dictionary];if(cookies.count)options[AVURLAssetHTTPCookiesKey]=cookies;if(ua.length)options[AVURLAssetHTTPHeaderFieldsKey]=@{@"User-Agent":ua};AVURLAsset *asset=[AVURLAsset URLAssetWithURL:url options:options];[asset loadValuesAsynchronouslyForKeys:@[@"tracks",@"duration"] completionHandler:^{AVAssetTrack *track=[asset tracksWithMediaType:AVMediaTypeVideo].firstObject;CGSize size=track?CGSizeApplyAffineTransform(track.naturalSize,track.preferredTransform):CGSizeZero;CGFloat width=fabs(size.width),height=fabs(size.height);NSString *codec=PVXMetadataCodec(track);if(width>0&&height>0){NSString *label=MIN(width,height)>=2160?([NSString stringWithFormat:@"4K · %.0f×%.0f",width,height]):[NSString stringWithFormat:@"%.0fp · %.0f×%.0f",MIN(width,height),width,height];if(codec.length)label=[label stringByAppendingFormat:@" · %@",codec];result[@"quality"]=label;result[@"width"]=@(width);result[@"height"]=@(height);}CGImageRef cg=nil;if(track){AVAssetImageGenerator *gen=[[AVAssetImageGenerator alloc] initWithAsset:asset];gen.appliesPreferredTrackTransform=YES;gen.maximumSize=CGSizeMake(480,480);cg=[gen copyCGImageAtTime:CMTimeMake(0,1) actualTime:NULL error:nil];}UIImage *image=cg?[UIImage imageWithCGImage:cg]:nil;if(cg)CGImageRelease(cg);if(image)result[@"thumbnail"]=image;dispatch_async(dispatch_get_main_queue(),^{PVXMetadataDeliver(key,result);});}];});}] resume];}
void PVXFetchMediaMetadata(NSDictionary *row,void(^done)(NSDictionary *)){if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{PVXFetchMediaMetadata(row,done);});return;}if(!PVXMetadataCache){PVXMetadataCache=[NSCache new];PVXMetadataCache.countLimit=256;PVXMetadataWaiters=[NSMutableDictionary dictionary];}NSString *url=PVXMetadataText(row[@"url"],16384),*key=[NSString stringWithFormat:@"%@|%@",row[@"kind"]?:@"video",url];NSDictionary *cached=[PVXMetadataCache objectForKey:key];if(cached){if(done)done(cached);return;}NSMutableArray *wait=PVXMetadataWaiters[key];if(wait){if(done)[wait addObject:[done copy]];return;}wait=[NSMutableArray array];if(done)[wait addObject:[done copy]];PVXMetadataWaiters[key]=wait;WKWebView *web=PVXCollectionWebView()?:PVXCurrentWebView();if(!web){PVXMetadataStart(row,@[],@"",key);return;}[web.configuration.websiteDataStore.httpCookieStore getAllCookies:^(NSArray *cookies){[web evaluateJavaScript:@"navigator.userAgent" completionHandler:^(id value,NSError *error){PVXMetadataStart(row,cookies,[value isKindOfClass:NSString.class]?value:@"",key);}];}];}
